from pathlib import Path
import sys
root=Path(sys.argv[1])
css_path=root/'assets/riftbound.css'
css=css_path.read_text()
# 10. Compact, separate Rika dock + polished Cursed Child picker styling.
css += r'''
/* Riftbound v0.3.1 · Cursed Child interaction architecture */
.rika-command-dock{--rika:#f4b9ff;border:1px solid #f4b9ff66;background:radial-gradient(circle at 8% 0,#f4b9ff1c,transparent 34%),linear-gradient(135deg,#100812f7,#090b13f5);margin:12px 0;box-shadow:inset 0 0 36px #f4b9ff0d,0 12px 38px #0007;position:relative;overflow:hidden}.rika-command-dock:before{content:"";pointer-events:none;background:repeating-linear-gradient(118deg,transparent 0 35px,#f4b9ff08 36px 37px);position:absolute;inset:0}.rika-command-dock>summary{list-style:none;cursor:pointer;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:12px;padding:11px 14px;display:grid;position:relative}.rika-command-dock>summary::-webkit-details-marker{display:none}.rika-command-dock>summary>b{width:38px;height:38px;border:1px solid #f4b9ff8c;color:#fff0ff;background:#0c0710;place-items:center;display:grid;font:900 20px var(--font-display);box-shadow:0 0 18px #f4b9ff26}.rika-command-dock>summary span small{color:#c893d2;font:700 7px var(--font-mono);letter-spacing:.14em;display:block}.rika-command-dock>summary span strong{color:#fff;font:900 15px var(--font-display);letter-spacing:.08em;display:block}.rika-command-dock>summary span p{color:#9d91a6;font:7px/1.45 var(--font-mono);margin:3px 0 0}.rika-command-dock>summary>em{color:#f4b9ff;font:800 8px var(--font-mono);font-style:normal;letter-spacing:.1em;white-space:nowrap}.rika-command-dock>summary>em i{font-style:normal;margin-left:8px;transition:transform .18s;display:inline-block}.rika-command-dock[open]>summary>em i{transform:rotate(180deg)}.rika-control-grid{border-top:1px solid #f4b9ff24;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:7px;padding:9px 10px 10px;display:grid;position:relative}.rika-control-grid>button{color:#e9e5ef;text-align:left;background:#ffffff05;border:1px solid #ffffff14;grid-template-columns:34px minmax(0,1fr);gap:8px;min-height:78px;padding:9px;display:grid;position:relative}.rika-control-grid>button:hover:not(:disabled){border-color:#f4b9ff8f;background:#f4b9ff0c;transform:translateY(-1px)}.rika-control-grid>button:disabled{opacity:.42;cursor:not-allowed}.rika-control-grid>button>b{width:30px;height:30px;border:1px solid #f4b9ff55;color:#f4b9ff;place-items:center;display:grid;font:900 14px var(--font-display)}.rika-control-grid>button span small{color:#9d779f;font:700 6px var(--font-mono);letter-spacing:.11em;display:block}.rika-control-grid>button span strong{color:#fff;font:800 10px var(--font-display);letter-spacing:.04em;display:block;margin-top:2px}.rika-control-grid>button span p{color:#867f90;font:6px/1.45 var(--font-mono);margin:4px 0 0}.rika-control-grid>button>em{color:#cfaed6;font:700 6px var(--font-mono);grid-column:2;font-style:normal}.rika-control-grid>button.full-rika{border-color:#f4b9ff54;background:linear-gradient(135deg,#f4b9ff10,#fff0)}.rika-control-grid>button.pure-love{border-color:#fff0ff7a;box-shadow:inset 0 0 22px #f4b9ff0d}.rika-control-empty{color:#8a7a8f;border-top:1px solid #f4b9ff18;margin:0;padding:12px 14px;font:7px var(--font-mono);position:relative}.factor-picker-overlay.cursed-mimicry,.factor-picker-overlay.cursed-domain{background:radial-gradient(circle at 50% 45%,#f4b9ff1a,#0000 34%),#07030aeF}.cursed-child-picker{border-color:#f4b9ff58;background:repeating-linear-gradient(135deg,#0000 0 42px,#f4b9ff05 43px 44px),linear-gradient(135deg,#f4b9ff10,#6c2a850c 55%,#0000),#09050b}.cursed-child-picker:before{background:linear-gradient(90deg,#f4b9ff,#0000 22% 78%,#fff) border-box}.cursed-child-picker .eyebrow{color:#f4b9ff}.cursed-technique-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;display:grid}.cursed-technique-card{color:#fff;text-align:left;background:linear-gradient(145deg,#f4b9ff08,#ffffff02);border:1px solid #f4b9ff29;min-height:160px;padding:0;display:grid;grid-template-rows:auto 1fr auto;position:relative;overflow:hidden}.cursed-technique-card:hover:not(:disabled){border-color:#f4b9ffaa;background:linear-gradient(145deg,#f4b9ff13,#ffffff04);transform:translateY(-2px);box-shadow:0 10px 28px #0008,0 0 22px #f4b9ff12}.cursed-technique-card:disabled{opacity:.38;cursor:not-allowed}.cursed-technique-card header{border-bottom:1px solid #f4b9ff1c;grid-template-columns:38px 1fr;align-items:center;gap:9px;padding:10px 12px;display:grid}.cursed-technique-card header>b{color:#f4b9ff;font:900 22px var(--font-display);text-shadow:0 0 16px #f4b9ff}.cursed-technique-card header small{color:#b994c0;font:6px var(--font-mono);letter-spacing:.11em;display:block}.cursed-technique-card header strong{color:#fff;font:900 13px var(--font-display);display:block;margin-top:2px}.cursed-technique-card>p{color:#aaa0af;font:7px/1.6 var(--font-mono);margin:0;padding:11px 12px}.cursed-technique-card footer{border-top:1px solid #ffffff0c;grid-template-columns:1fr 1fr auto;align-items:center;gap:8px;padding:8px 11px;display:grid}.cursed-technique-card footer span{color:#c6a9cb;font:700 6px var(--font-mono);letter-spacing:.08em}.cursed-technique-card footer em{color:#fff;font:900 7px var(--font-mono);font-style:normal}.cursed-technique-card.fresh:after{content:"FRESH COPY";color:#140817;background:#f4b9ff;font:900 5px var(--font-mono);letter-spacing:.08em;padding:3px 5px;position:absolute;top:7px;right:7px}.cursed-technique-lock{color:#ff9da9;background:#1c090ee8;border-top:1px solid #ff728733;padding:5px 10px;font:700 6px/1.35 var(--font-mono);font-style:normal}@media(max-width:760px){.cursed-technique-grid{grid-template-columns:1fr}.rika-command-dock>summary{grid-template-columns:40px 1fr}.rika-command-dock>summary>em{grid-column:1/-1}.rika-control-grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.rika-control-grid{grid-template-columns:1fr}}
'''
css_path.write_text(css)
print("Applied Cursed Child UI styling")
